(7168242, 1099543, 30982, '<td valign="top">The light here is amazing.  Hopefully people stop to appreciate just how gently it caresses the land and paints the windows.</td>', 'The light here is amazing.  Hopefully people stop to appreciate just how gently it caresses the land and paints the windows.', '2014-02-02 21:55:11.000000', NULL, 1),
(7168243, 1098724, 30982, '<td valign="top">Such amazing eyes!  A lovely, gentle portrait.</td>', 'Such amazing eyes!  A lovely, gentle portrait.', '2014-02-02 21:55:47.000000', NULL, 1),
(7168245, 1099167, 30982, '<td valign="top">LOL!  This is just a lot of fun.  Especially those guys in the mud.</td>', 'LOL!  This is just a lot of fun.  Especially those guys in the mud.', '2014-02-02 21:56:26.000000', NULL, 1),
