(7170972, 1100564, 147314, '<td valign="top">My absolute favourite, beautiful. Great pose, good use of DoF, lovely warm colours, it all comes together!</td>', 'My absolute favourite, beautiful. Great pose, good use of DoF, lovely warm colours, it all comes together!', '2014-02-06 15:47:04.000000', NULL, 1),
