INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7170989, 1100515, 147314, '<td valign="top">Didn''t see them last year, but I really have to see them this year, such lovely birds. Great image!</td>', 'Didn''t see them last year, but I really have to see them this year, such lovely birds. Great image!', '2014-02-06 15:56:16.000000', NULL, 1),
(7170992, 1100338, 147314, '<td valign="top">I can smell the British landscape, am I right?. Great ''moody'' image.</td>', 'I can smell the British landscape, am I right?. Great ''moody'' image.', '2014-02-06 15:57:43.000000', NULL, 1),
(7170993, 1099224, 147314, '<td valign="top">Fantastic shot, the focus on that orchid (?) and the out-of-focus background. Beautiful!</td>', 'Fantastic shot, the focus on that orchid (?) and the out-of-focus background. Beautiful!', '2014-02-06 15:59:14.000000', NULL, 1),
(7170994, 1100486, 147314, '<td valign="top">The vista is breathtaking, the processing maybe just too HDR? But an amazing image it is.</td>', 'The vista is breathtaking, the processing maybe just too HDR? But an amazing image it is.', '2014-02-06 16:00:53.000000', NULL, 1),
(7170996, 1100561, 147314, '<td valign="top">Love the colours in this image and those ''jewels'' are amazing. Good find!</td>', 'Love the colours in this image and those ''jewels'' are amazing. Good find!', '2014-02-06 16:02:13.000000', NULL, 1),
(7170997, 1100245, 147314, '<td valign="top">You always see the aerial view of the Niagara, but I find thiS POV very refreshing. Great shot!</td>', 'You always see the aerial view of the Niagara, but I find thiS POV very refreshing. Great shot!', '2014-02-06 16:04:22.000000', NULL, 1),
(7170999, 1100552, 147314, '<td valign="top">Magnificent sunflower shot, I like the background with all the flowers looking your way in contrast with the one in focus.</td>', 'Magnificent sunflower shot, I like the background with all the flowers looking your way in contrast with the one in focus.', '2014-02-06 16:06:01.000000', NULL, 1),
(7171001, 1100587, 147314, '<td valign="top">Lovely lighted portrait, one of the best in this challenge!</td>', 'Lovely lighted portrait, one of the best in this challenge!', '2014-02-06 16:06:48.000000', NULL, 1),
(7171002, 1099047, 147314, '<td valign="top">Lovely shot of this boy. The vignette is just too much for me.</td>', 'Lovely shot of this boy. The vignette is just too much for me.', '2014-02-06 16:08:05.000000', NULL, 1),
(7171003, 1100513, 147314, '<td valign="top">Would love to be here (Iceland?). Beautiful image.</td>', 'Would love to be here (Iceland?). Beautiful image.', '2014-02-06 16:09:37.000000', NULL, 1),
(7171005, 1100436, 173844, '<td valign="top">Wonderful detail, rhythm and drama in this terrific image reminiscent of Ansel Adams.  It feels like the grouping of three bushes in the foreground is being picked out by sunlight.  The undulations in the sand function as hundreds of lines leading to a sky boiling over back at the viewer.  One of my top five.</td>', 'Wonderful detail, rhythm and drama in this terrific image reminiscent of Ansel Adams.  It feels like the grouping of three bushes in the foreground is being picked out by sunlight.  The undulations in the sand function as hundreds of lines leading to a sky boiling over back at the viewer.  One of my top five.', '2014-02-06 16:12:50.000000', NULL, 1),
(7171013, 1098734, 173844, '<td valign="top">Stirring, stunning and sublime.  Tumultuous movement amidst the mountains and sky.  So much is elicited from a limited palette.  I''m full of admiration for this beautiful image.  Needless to say, my favorite of the challenge.</td>', 'Stirring, stunning and sublime.  Tumultuous movement amidst the mountains and sky.  So much is elicited from a limited palette.  I''m full of admiration for this beautiful image.  Needless to say, my favorite of the challenge.', '2014-02-06 16:30:25.000000', NULL, 1),
(7171014, 1100815, 173844, '<td valign="top">An adorable child walking happily across a wet expanse.  Wonderful composition  within a well-chosen square format.  You could also say that it''s a study of reflections, carried off so winningly in black and white.  One of my top five.</td>', 'An adorable child walking happily across a wet expanse.  Wonderful composition  within a well-chosen square format.  You could also say that it''s a study of reflections, carried off so winningly in black and white.  One of my top five.', '2014-02-06 16:30:34.000000', NULL, 1),
(7171015, 1100734, 173844, '<td valign="top">Beautiful moody image, bathed in gold.  The man seems to be walking into an epiphany.  The rocks to the right have lots of personality.  It''s the tonation that brings so much extra to this picture.  The only distraction is the car peeking out above the rocks.  One of my top five.</td>', 'Beautiful moody image, bathed in gold.  The man seems to be walking into an epiphany.  The rocks to the right have lots of personality.  It''s the tonation that brings so much extra to this picture.  The only distraction is the car peeking out above the rocks.  One of my top five.', '2014-02-06 16:30:37.000000', NULL, 1),
(7171016, 1100290, 23484, '<td valign="top">Forever Beautiful.9</td>', 'Forever Beautiful.9', '2014-02-06 16:31:22.000000', NULL, 1),
(7171019, 1100622, 23484, '<td valign="top">That is a very nice image. Perfect composition and background.9</td>', 'That is a very nice image. Perfect composition and background.9', '2014-02-06 16:31:57.000000', NULL, 1),
(7171021, 1099292, 23484, '<td valign="top">Great bourbon!</td>', 'Great bourbon!', '2014-02-06 16:32:17.000000', NULL, 1),
