(7171028, 1099664, 23484, '<td valign="top">Not someplace I''d want to hike, but very beautiful.</td>', 'Not someplace I''d want to hike, but very beautiful.', '2014-02-06 16:34:25.000000', NULL, 1),
(7171031, 1100189, 23484, '<td valign="top">He kind of looks like Harrison Ford.</td>', 'He kind of looks like Harrison Ford.', '2014-02-06 16:36:12.000000', NULL, 1),
(7171032, 1099054, 23484, '<td valign="top">Very nice portrait.</td>', 'Very nice portrait.', '2014-02-06 16:36:34.000000', NULL, 1),
(7171033, 1098721, 173844, '<td valign="top">This beautiful image masterfully catches that last flick of daylight.  Now you can delve into the deep shadow of the hillside and be rewarded by the excellent delineation of nuanced tones.  Really quite perfect (which I guess is impossibly more than perfect).  One of my top five.</td>', 'This beautiful image masterfully catches that last flick of daylight.  Now you can delve into the deep shadow of the hillside and be rewarded by the excellent delineation of nuanced tones.  Really quite perfect (which I guess is impossibly more than perfect).  One of my top five.', '2014-02-06 16:37:47.000000', NULL, 1),
(7171059, 1099193, 100393, '<td valign="top">Wow. Such an honest portrayal of a moment. Unfettered, graphic, initimate, complex, simple.</td>', 'Wow. Such an honest portrayal of a moment. Unfettered, graphic, initimate, complex, simple.', '2014-02-06 18:00:08.000000', NULL, 1),
(7171060, 1098849, 100393, '<td valign="top">One of the best photographs I''ve seen on DPC - like ever.<br/> <br/>I love the ground glass look - reminds me of some of the output from Cory''s bespoke rig.<br/> <br/>This would have looked great in black and white too - but I pleased you went with a colour rendition.</td>', 'One of the best photographs I''ve seen on DPC - like ever. I love the ground glass look - reminds me of some of the output from Cory''s bespoke rig. This would have looked great in black and white too - but I pleased you went with a colour rendition.', '2014-02-06 18:02:26.000000', NULL, 1),
(7171061, 1100158, 100393, '<td valign="top">So much going on! Precision and chaos all in one image. A photo with such intensity of scene that I can almost hear it. The held shadows. I love how there are crucial elements spread all around the frame.<br/> <br/>Great stuff!</td>', 'So much going on! Precision and chaos all in one image. A photo with such intensity of scene that I can almost hear it. The held shadows. I love how there are crucial elements spread all around the frame. Great stuff!', '2014-02-06 18:05:11.000000', NULL, 1),
(7171062, 1099402, 100393, '<td valign="top">Lovely precision.</td>', 'Lovely precision.', '2014-02-06 18:05:28.000000', NULL, 1),
(7171064, 1099384, 100393, '<td valign="top">This is pretty spectacular.</td>', 'This is pretty spectacular.', '2014-02-06 18:06:29.000000', NULL, 1),
(7171065, 1099758, 100393, '<td valign="top">Great structure - auto-art.</td>', 'Great structure - auto-art.', '2014-02-06 18:07:09.000000', NULL, 1),
(7171066, 1099805, 100393, '<td valign="top">Great sense of depth but the person makes it.</td>', 'Great sense of depth but the person makes it.', '2014-02-06 18:07:32.000000', NULL, 1),
