(7171945, 1099384, 129147, '<td valign="top">Congratulations! A great image.<br/></td>', 'Congratulations! A great image.', '2014-02-07 09:55:13.000000', NULL, 0),
(7171956, 1100177, 70270, '<td valign="top">I liked this one, soft colors, dreamy feel, a nice tiny macro shot -- I love looking into the little world around us.  I am surprised this didn''t garner any comments during the challenge.</td>', 'I liked this one, soft colors, dreamy feel, a nice tiny macro shot -- I love looking into the little world around us.  I am surprised this didn''t garner any comments during the challenge.', '2014-02-07 10:20:10.000000', NULL, 0),
(7171957, 1098784, 12611, '<td valign="top">I love how it is easy to be enchanted by the eyes, and while the spell is on, notice the textures and shapes in the periphery; the fine detail of the hairline, the jungle animal skin patterns of the dark rain. Hauntingly memorable.</td>', 'I love how it is easy to be enchanted by the eyes, and while the spell is on, notice the textures and shapes in the periphery; the fine detail of the hairline, the jungle animal skin patterns of the dark rain. Hauntingly memorable.', '2014-02-07 10:26:03.000000', NULL, 0),
(7171959, 1100762, 12611, '<td valign="top">fantastic colors. a stand out.</td>', 'fantastic colors. a stand out.', '2014-02-07 10:27:11.000000', NULL, 0),
(7171962, 1099541, 12611, '<td valign="top">I''ve taken shots there many times, but not like this one, the movement, the kiss, the colors,-great work.</td>', 'I''ve taken shots there many times, but not like this one, the movement, the kiss, the colors,-great work.', '2014-02-07 10:28:34.000000', NULL, 0),
(7171963, 1099463, 12611, '<td valign="top">Lovely use of the blue/gold complimentary palette, and foreground-background tone elements. quite pleasing.</td>', 'Lovely use of the blue/gold complimentary palette, and foreground-background tone elements. quite pleasing.', '2014-02-07 10:30:16.000000', NULL, 0),
(7171964, 1100734, 12611, '<td valign="top">You are the master of the solitary individual shot. lots to think about, and a great finish.</td>', 'You are the master of the solitary individual shot. lots to think about, and a great finish.', '2014-02-07 10:32:18.000000', NULL, 0),
(7171968, 1100730, 12611, '<td valign="top">I have to give you credit, this evokes a great deal of emotion that doesn''t seem possible in a sky moon shot-Beautiful job.</td>', 'I have to give you credit, this evokes a great deal of emotion that doesn''t seem possible in a sky moon shot-Beautiful job.', '2014-02-07 10:35:01.000000', NULL, 0),
(7171969, 1100073, 61234, '<td valign="top">Congrats on a great finish! Beautiful scene you captured!</td>', 'Congrats on a great finish! Beautiful scene you captured!', '2014-02-07 10:35:02.000000', NULL, 0),
